describe('Date Picker Keyboard Navigation', () => {
  beforeEach(() => {
    cy.visit('/date-picker');
  });

  it('should allow full date picker operation using only keyboard navigation', () => {
    // Focus on the date picker input field
    cy.get('[data-testid="date-picker-input"]').focus();

    // Press Enter to open the calendar view
    cy.get('[data-testid="date-picker-input"]').type('{enter}');

    // Verify calendar is visible
    cy.get('[data-testid="calendar-popup"]').should('be.visible');

    // Navigate to the next month using right arrow key
    cy.get('[data-testid="calendar-popup"]').type('{rightarrow}');

    // Verify month changed
    cy.get('[data-testid="calendar-month-display"]').should('contain', 'October');

    // Navigate to previous month using left arrow key
    cy.get('[data-testid="calendar-popup"]').type('{leftarrow}');

    // Verify month changed back
    cy.get('[data-testid="calendar-month-display"]').should('contain', 'September');

    // Navigate between days using up and down arrow keys
    cy.get('[data-testid="calendar-popup"]').type('{uparrow}');
    cy.get('[data-testid="calendar-popup"]').type('{uparrow}');

    // Verify day changed
    cy.get('[data-testid="calendar-day-display"]').should('contain', '25');

    // Navigate to next day using right arrow key
    cy.get('[data-testid="calendar-popup"]').type('{rightarrow}');

    // Verify day changed
    cy.get('[data-testid="calendar-day-display"]').should('contain', '26');

    // Press Enter to select the date
    cy.get('[data-testid="calendar-popup"]').type('{enter}');

    // Verify date is selected and input is populated
    cy.get('[data-testid="date-picker-input"]').should('have.value', '2023-09-26');

    // Verify calendar closes
    cy.get('[data-testid="calendar-popup"]').should('not.exist');
  });

  it('should handle keyboard navigation with edge cases like month boundaries and invalid inputs', () => {
    // Focus on date picker input
    cy.get('[data-testid="date-picker-input"]').focus();

    // Open calendar
    cy.get('[data-testid="date-picker-input"]').type('{enter}');

    // Navigate to the first day of the month
    cy.get('[data-testid="calendar-popup"]').type('{leftarrow}');
    cy.get('[data-testid="calendar-popup"]').type('{leftarrow}');

    // Verify month changed
    cy.get('[data-testid="calendar-month-display"]').should('contain', 'August');

    // Navigate to the first day of the month
    cy.get('[data-testid="calendar-popup"]').type('{uparrow}');
    cy.get('[data-testid="calendar-popup"]').type('{uparrow}');
    cy.get('[data-testid="calendar-popup"]').type('{uparrow}');

    // Verify day is 1
    cy.get('[data-testid="calendar-day-display"]').should('contain', '1');

    // Navigate to the last day of the month
    cy.get('[data-testid="calendar-popup"]').type('{rightarrow}');
    cy.get('[data-testid="calendar-popup"]').type('{rightarrow}');
    cy.get('[data-testid="calendar-popup"]').type('{rightarrow}');
    cy.get('[data-testid="calendar-popup"]').type('{rightarrow}');
    cy.get('[data-testid="calendar-popup"]').type('{rightarrow}');
    cy.get('[data-testid="calendar-popup"]').type('{rightarrow}');
    cy.get('[data-testid="calendar-popup"]').type('{rightarrow}');
    cy.get('[data-testid="calendar-popup"]').type('{rightarrow}');

    // Verify last day is selected
    cy.get('[data-testid="calendar-day-display"]').should('contain', '31');

    // Press Escape to close calendar without selecting a date
    cy.get('[data-testid="calendar-popup"]').type('{escape}');

    // Verify date input is not populated
    cy.get('[data-testid="date-picker-input"]').should('have.value', '');

    // Verify calendar is closed
    cy.get('[data-testid="calendar-popup"]').should('not.exist');
  });
});
